]}]},"expected":["PROVIDER:INVALID_PRESENTATION:e1"]},{"name":"embed: presentation invalid","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"youtube","data":{"kind":"video","id":"dQw4w9WgXcQ","presentation":"iframe"}}}]}]},"expected":["PROVIDER:INVALID_PRESENTATION:e1"]},{"name":"embed: aspect invalid","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"youtube","data":{"kind":"video","id":"dQw4w9WgXcQ","presentation":"embed","aspect":"21:9"}}}]}]},"expected":["PROVIDER:INVALID_ASPECT:e1"]},{"name":"embed: aspect auto valid","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"spotify","data":{"kind":"track","id":"4uLU6hMCjMI75M1A2tKUQC","presentation":"embed","aspect":"auto"}}}]}]},"expected":[]},{"name":"embed: caption 80 chars valid","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"youtube","data":{"kind":"video","id":"dQw4w9WgXcQ","presentation":"card","caption":"cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc"}}}]}]},"expected":[]},{"name":"embed: caption 81 chars","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"youtube","data":{"kind":"video","id":"dQw4w9WgXcQ","presentation":"card","caption":"ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc"}}}]}]},"expected":["PROVIDER:INVALID_CAPTION:e1"]},{"name":"embed: caption unsafe markup","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"youtube","data":{"kind":"video","id":"dQw4w9WgXcQ","presentation":"card","caption":"<script>alert(1)</script>"}}}]}]},"expected":["UNSAFE_PAYLOAD_CONTENT:e1.payload.data.caption"]},{"name":"embed: caption javascript URL","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"youtube","data":{"kind":"video","id":"dQw4w9WgXcQ","presentation":"card","caption":"javascript:alert(1)"}}}]}]},"expected":["UNSAFE_PAYLOAD_CONTENT:e1.payload.data.caption"]},{"name":"embed: iframe markup smuggled as the id","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"youtube","data":{"kind":"video","id":"<iframe src=x>","presentation":"embed"}}}]}]},"expected":["PROVIDER:INVALID_ID:e1","UNSAFE_PAYLOAD_CONTENT:e1.payload.data.id"]},{"name":"embed: a URL as the id","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"youtube","data":{"kind":"video","id":"https://www.youtube.com/watch?v=dQw4w9WgXcQ","presentation":"embed"}}}]}]},"expected":["PROVIDER:INVALID_ID:e1"]},{"name":"embed: a url smuggled in an extra key is still just data","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"youtube","data":{"kind":"video","id":"dQw4w9WgXcQ","presentation":"card","src":"https://evil.example/"}}}]}]},"expected":[]},{"name":"embed: extra key with an event handler is rejected","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"youtube","data":{"kind":"video","id":"dQw4w9WgXcQ","presentation":"card","note":"x onload=alert(1)"}}}]}]},"expected":["UNSAFE_PAYLOAD_CONTENT:e1.payload.data.note"]},{"name":"embed: kind missing","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"youtube","data":{"id":"dQw4w9WgXcQ","presentation":"embed"}}}]}]},"expected":["PROVIDER:INVALID_KIND:e1"]},{"name":"embed: kind is a number","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"youtube","data":{"kind":5,"id":"dQw4w9WgXcQ","presentation":"embed"}}}]}]},"expected":["PROVIDER:INVALID_KIND:e1"]},{"name":"embed: __proto__ style kind","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"youtube","data":{"kind":"__proto__","id":"dQw4w9WgXcQ","presentation":"embed"}}}]}]},"expected":["PROVIDER:INVALID_KIND:e1"]},{"name":"embed: data missing","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":100,"height":100,"z":0,"payload":{"providerKey":"youtube"}}]}]},"expected":["PROVIDER_DATA_NOT_OBJECT:e1"]},{"name":"embed: data is an array","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"youtube","data":[]}}]}]},"expected":["PROVIDER_DATA_NOT_OBJECT:e1"]},{"name":"embed: data is a string","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"youtube","data":"https://youtu.be/x"}}]}]},"expected":["PROVIDER_DATA_NOT_OBJECT:e1"]},{"name":"embed: provider key different case is unknown","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"YouTube","data":{"kind":"video","id":"dQw4w9WgXcQ","presentation":"embed"}}}]}]},"expected":["UNSUPPORTED_PROVIDER:e1"]},{"name":"embed: provider key with a space","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"you tube","data":{"kind":"video","id":"dQw4w9WgXcQ","presentation":"embed"}}}]}]},"expected":["UNSUPPORTED_PROVIDER:e1"]},{"name":"embed: unregistered provider (vimeo) is unsupported","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"e1","type":"embed","x":10,"y":10,"width":600,"height":340,"z":0,"payload":{"providerKey":"vimeo","data":{"kind":"video","id":"123456","presentation":"embed"}}}]}]},"expected":["UNSUPPORTED_PROVIDER:e1"]},{"name":"embed: several providers in one Wall","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"a","type":"embed","x":10,"y":0,"width":600,"height":340,"z":0,"payload":{"providerKey":"youtube","data":{"kind":"video","id":"dQw4w9WgXcQ","presentation":"embed"}}},{"id":"b","type":"embed","x":10,"y":400,"width":600,"height":340,"z":0,"payload":{"providerKey":"spotify","data":{"kind":"track","id":"4uLU6hMCjMI75M1A2tKUQC","presentation":"embed"}}},{"id":"c","type":"embed","x":10,"y":800,"width":600,"height":340,"z":0,"payload":{"providerKey":"twitch","data":{"kind":"channel","id":"shroud","presentation":"card"}}},{"id":"d","type":"embed","x":10,"y":1200,"width":600,"height":340,"z":0,"payload":{"providerKey":"discord","data":{"kind":"invite","id":"abcDEF","presentation":"link"}}}]}]},"expected":[]},{"name":"embed: one bad provider among good ones reports only the bad one","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"a","type":"embed","x":10,"y":0,"width":600,"height":340,"z":0,"payload":{"providerKey":"youtube","data":{"kind":"video","id":"dQw4w9WgXcQ","presentation":"embed"}}},{"id":"b","type":"embed","x":10,"y":400,"width":600,"height":340,"z":0,"payload":{"providerKey":"spotify","data":{"kind":"track","id":"bad","presentation":"embed"}}}]}]},"expected":["PROVIDER:INVALID_ID:b"]},{"name":"mixed Wall: text, image, shapes, GamID blocks, embeds, backgrounds and stages together","doc":{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"s1","elements":[{"id":"t","type":"text","x":10,"y":0,"width":600,"height":150,"z":0,"payload":{"text":"Your text","fontFamily":"orbitron","fontSize":96,"fontWeight":700,"italic":false,"underline":false,"color":"#ffffff","align":"center","lineHeight":1.2,"letterSpacing":0,"opacity":1,"direction":"auto","wrap":true}},{"id":"i","type":"image","x":10,"y":200,"width":100,"height":100,"z":0,"payload":{"assetId":"3f2b8c1e-5a4d-4e7b-9c60-1d2e3f4a5b6c","fit":"cover","posX":50,"posY":50,"opacity":1}},{"id":"r","type":"rect","x":10,"y":400,"width":100,"height":100,"z":0,"payload":{"fill":"#aabbcc"}},{"id":"g","type":"gamid","x":10,"y":600,"width":600,"height":300,"z":0,"payload":{"block":"games","initial":10}},{"id":"e","type":"embed","x":10,"y":950,"width":600,"height":340,"z":0,"payload":{"providerKey":"youtube","data":{"kind":"video","id":"dQw4w9WgXcQ","presentation":"embed"}}}]},{"id":"s2","elements":[{"id":"f","type":"embed","x":10,"y":0,"width":600,"height":340,"z":0,"payload":{"providerKey":"steam","data":{"kind":"app","id":"730","presentation":"embed"}}}],"background":{"kind":"gradient","from":"#000000","to":"#111111","angle":90}}],"background":{"kind":"color","color":"#0d0b14"}},"expected":[]}]$w2c$::jsonb;
  default_doc jsonb := $w2d${"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[]}]}$w2d$::jsonb;
  doc_one jsonb := '{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"r1","type":"rect","x":10,"y":20,"width":300,"height":200,"z":1,"payload":{"fill":"#aabbcc"}}]}]}';
  doc_two jsonb := '{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"stage_1","elements":[{"id":"r1","type":"rect","x":50,"y":60,"width":300,"height":200,"z":2,"payload":{"fill":"#112233"}},{"id":"r2","type":"rect","x":0,"y":0,"width":10,"height":10,"z":0,"payload":{"fill":"#ffffff"}}]},{"id":"stage_2","elements":[]}]}';
  doc_b jsonb := '{"schemaVersion":1,"canvas":{"width":1000,"height":1778},"stages":[{"id":"only","elements":[{"id":"b1","type":"rect","x":1,"y":1,"width":5,"height":5,"z":0,"payload":{"fill":"#000000"}}]}]}';
begin
  -- real identities may already have their own private Walls; the test only ever looks at (and creates) rows for its own disposable identities
  select count(*) into rows_before from public.wall_drafts d join public.entities e on e.entity_id = d.entity_id where e.gamid_handle like 'zw2%';
  res := res || jsonb_build_object('step', 'no Wall rows exist for the disposable test identities before the test (nothing seeded)', 'pass', rows_before = 0);

  -- helper: run one statement as anon / authenticated the way PostgREST does, returning its first column or the error as ERR:sqlstate:message[:detail]
  execute $fn$
    create function pg_temp.w2_run(p_uid uuid, p_role text, p_sql text) returns text language plpgsql as $f$
    declare o text; det text;
    begin
      perform set_config('request.jwt.claims', case when p_uid is null then json_build_object('role', p_role)::text else json_build_object('sub', p_uid, 'role', p_role)::text end, true);
      execute 'set local role ' || p_role;
      begin
        execute p_sql into o;
      exception when others then
        get stacked diagnostics det = pg_exception_detail;
        o := 'ERR:' || sqlstate || ':' || sqlerrm || case when det is not null then ':' || det else '' end;
      end;
      reset role;
      return o;
    end $f$;
  $fn$;

  insert into auth.users (id, email, email_confirmed_at) values (ua, 'zw2-a@example.invalid', now()), (ub, 'zw2-b@example.invalid', now()), (uc, 'zw2-c@example.invalid', now());
  perform set_config('request.jwt.claims', json_build_object('sub', ua, 'role', 'authenticated')::text, true);
  set local role authenticated; perform 1 from public.create_solo_identity('zw2a', 'Zed A', date '1990-01-01', 'en'); reset role;
  perform set_config('request.jwt.claims', json_build_object('sub', ub, 'role', 'authenticated')::text, true);
  set local role authenticated; perform 1 from public.create_solo_identity('zw2b', 'Zed B', date '1990-01-01', 'en'); reset role;
  select e.entity_id into ent_a from public.entities e where e.gamid_handle = 'zw2a';
  select e.entity_id into ent_b from public.entities e where e.gamid_handle = 'zw2b';
  -- uc deliberately has NO identity

  -- ===== structure and privileges =====
  select relrowsecurity into flag from pg_class where oid = 'public.wall_drafts'::regclass;
  res := res || jsonb_build_object('step', 'RLS is enabled on wall_drafts', 'pass', coalesce(flag, false));
  select count(*) into cnt from pg_constraint c where c.conrelid = 'public.wall_drafts'::regclass and c.conname = 'wall_drafts_one_per_identity' and c.contype = 'u';
  res := res || jsonb_build_object('step', 'one Wall per identity is a database unique constraint', 'pass', cnt = 1);
  select count(*) into cnt from pg_constraint c where c.conrelid = 'public.wall_drafts'::regclass and c.conname = 'wall_drafts_document_is_valid' and c.contype = 'c';
  res := res || jsonb_build_object('step', 'the document validator is also a table CHECK (defense in depth)', 'pass', cnt = 1);
  select count(*) into cnt from information_schema.columns c where c.table_schema = 'public' and c.table_name = 'wall_drafts' and c.column_name in ('owner_id', 'user_id', 'wall_count', 'is_public', 'published');
  res := res || jsonb_build_object('step', 'no owner-user, wall-count or publish columns exist (ownership is the entity; publishing is not modeled)', 'pass', cnt = 0);
  res := res || jsonb_build_object('step', 'anon has no table privilege on wall_drafts',
    'pass', not (has_table_privilege('anon', 'public.wall_drafts', 'select') or has_table_privilege('anon', 'public.wall_drafts', 'insert') or has_table_privilege('anon', 'public.wall_drafts', 'update') or has_table_privilege('anon', 'public.wall_drafts', 'delete')));
  res := res || jsonb_build_object('step', 'authenticated has no table privilege on wall_drafts (RPC-only)',
    'pass', not (has_table_privilege('authenticated', 'public.wall_drafts', 'select') or has_table_privilege('authenticated', 'public.wall_drafts', 'insert') or has_table_privilege('authenticated', 'public.wall_drafts', 'update') or has_table_privilege('authenticated', 'public.wall_drafts', 'delete')));
  res := res || jsonb_build_object('step', 'the three owner RPCs are executable by authenticated and NOT by anon',
    'pass', has_function_privilege('authenticated', 'public.ensure_my_wall_draft()', 'execute') and has_function_privilege('authenticated', 'public.get_my_wall_draft()', 'execute') and has_function_privilege('authenticated', 'public.save_my_wall_draft(jsonb,bigint)', 'execute')
      and not has_function_privilege('anon', 'public.ensure_my_wall_draft()', 'execute') and not has_function_privilege('anon', 'public.get_my_wall_draft()', 'execute') and not has_function_privilege('anon', 'public.save_my_wall_draft(jsonb,bigint)', 'execute'));
  res := res || jsonb_build_object('step', 'validators and owner resolution are not executable by any client role',
    'pass', not (has_function_privilege('authenticated', 'private.wall_document_errors(jsonb)', 'execute') or has_function_privilege('anon', 'private.wall_document_errors(jsonb)', 'execute') or has_function_privilege('authenticated', 'private.wall_owned_entity_id()', 'execute') or has_function_privilege('anon', 'private.save_my_wall_draft_impl(jsonb,bigint)', 'execute') or has_function_privilege('authenticated', 'private.wall_text_payload_errors(jsonb)', 'execute') or has_function_privilege('anon', 'private.wall_in_range(jsonb,float8,float8)', 'execute')));
  select count(*) into cnt from pg_proc p join pg_namespace s on s.oid = p.pronamespace
   where s.nspname = 'public' and p.proname in ('ensure_my_wall_draft', 'get_my_wall_draft', 'save_my_wall_draft') and p.prosecdef;
  res := res || jsonb_build_object('step', 'public wrappers are SECURITY INVOKER', 'pass', cnt = 0);
  select count(*) into cnt from pg_proc p join pg_namespace s on s.oid = p.pronamespace
   where s.nspname = 'private' and p.proname in ('ensure_my_wall_draft_impl', 'get_my_wall_draft_impl', 'save_my_wall_draft_impl', 'wall_owned_entity_id') and p.prosecdef and exists (select 1 from unnest(p.proconfig) c where c = 'search_path=""');
  res := res || jsonb_build_object('step', 'private implementations are SECURITY DEFINER with a fixed empty search_path', 'pass', cnt = 4);
  res := res || jsonb_build_object('step', 'a brand-new Wall starts as exactly the W1 createDocument() contract', 'pass', private.wall_new_document() = default_doc);

  -- ===== authentication and identity resolution =====
  out := pg_temp.w2_run(null, 'anon', 'select to_jsonb(d)::text from public.get_my_wall_draft() d');
  res := res || jsonb_build_object('step', 'anon cannot call get_my_wall_draft', 'pass', out like 'ERR:42501:%', 'got', out);
  out := pg_temp.w2_run(null, 'anon', 'select to_jsonb(d)::text from public.ensure_my_wall_draft() d');
  res := res || jsonb_build_object('step', 'anon cannot call ensure_my_wall_draft', 'pass', out like 'ERR:42501:%', 'got', out);
  out := pg_temp.w2_run(null, 'anon', format('select to_jsonb(d)::text from public.save_my_wall_draft(%L::jsonb, 1) d', default_doc::text));
  res := res || jsonb_build_object('step', 'anon cannot call save_my_wall_draft', 'pass', out like 'ERR:42501:%', 'got', out);
